from collections import defaultdict

def longest_apple_substring(s):
    dp = defaultdict(int)
    longest = 0
    for i in range(len(s)):
        if s[i] == '1':
            dp[i] = dp[i-1] + 1
        else:
            dp[i] = 0
        longest = max(longest, dp[i])
    return longest

