import sys

def solve(n, operations):
    sequence = [0]
    averages = []

    for operation in operations:
        if operation[0] == 1:
            ai, xi = operation[1], operation[2]
            sequence[:ai] = [x + xi for x in sequence[:ai]]
        elif operation[0] == 2:
            ki = operation[1]
            sequence.append(ki)
        else:
            if len(sequence) > 1:
                sequence.pop()

        averages.append(sum(sequence) / len(sequence))

    return averages

