def is_easily_playable(S):
    odd_positions = S[::2]  # Extract characters at odd positions
    even_positions = S[1::2]  # Extract characters at even positions

    # Check if all characters in odd positions are R, U, or D
    for char in odd_positions:
        if char not in ['R', 'U', 'D']:
            return "No"

    # Check if all characters in even positions are L, U, or D
    for char in even_positions:
        if char not in ['L', 'U', 'D']:
            return "No"

    return "Yes"

