def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)

def solve(n, a):
    dp = [1] * n
    ans = 1
    for i in range(1, n):
        for j in range(i):
            if gcd(a[i], a[j]) > 1 and dp[i] < dp[j] + 1:
                dp[i] = dp[j] + 1
        ans = max(ans, dp[i])
    return ans

