def count_non_zero_area_triangles(n, points):
    # Helper function to calculate the area of a triangle using the Shoelace formula
    def triangle_area(p1, p2, p3):
        return abs(p1[0]*(p2[1]-p3[1]) + p2[0]*(p3[1]-p1[1]) + p3[0]*(p1[1]-p2[1])) / 2

    # Initialize the count of non-zero area triangles
    non_zero_area_triangles = 0

    # Generate all possible combinations of 3 points
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                # Check if the points form a non-zero area triangle
                if triangle_area(points[i], points[j], points[k]) != 0:
                    non_zero_area_triangles += 1

    return non_zero_area_triangles

