def min_digits_product(N):
    min_digits = float('inf')
    for i in range(1, int(N**0.5) + 1):
        if N % i == 0:
            num1 = i
            num2 = N // i
            min_digits = min(min_digits, max(len(str(num1)), len(str(num2))))
    return min_digits

