def find_cycle(n, edges):
    visited = [False] * n
    recursive_visited = [False] * n
    for i in range(n):
        if not visited[i] and not recursive_visited[i]:
            if has_cycle(edges, visited, recursive_visited, i):
                return 1
    return 0

def has_cycle(edges, visited, recursive_visited, node):
    visited[node] = True
    recursive_visited[node] = True
    for neighbour in edges[node]:
        if not visited[neighbour]:
            if has_cycle(edges, visited, recursive_visited, neighbour):
                return True
        elif recursive_visited[neighbour]:
            return True
    recursive_visited[node] = False
    return False

