import heapq

def bfs(graph, start, end):
    visited = set()
    queue = [(start, 0)]
    while queue:
        current, distance = heapq.heappop(queue)
        if current == end:
            return distance
        visited.add(current)
        for neighbor in graph[current]:
            if neighbor not in visited:
                heapq.heappush(queue, (neighbor, distance + 1))
    return -1

