import heapq

def get_min_distance(n, graph, start, end):
    distance = [float('inf')] * (n + 1)
    distance[start] = 0
    pq = [(0, start)]

    while pq:
        dist, node = heapq.heappop(pq)
        if dist > distance[node]:
            continue
        if node == end:
            return dist
        for neighbor, weight in graph[node]:
            new_dist = dist + weight
            if new_dist < distance[neighbor]:
                distance[neighbor] = new_dist
                heapq.heappush(pq, (new_dist, neighbor))

    return float('inf')

def compute_brain_latency(n, m, graph):
    distances = [get_min_distance(n, graph, i, j) for i in range(1, n + 1) for j in range(i + 1, n + 1)]
    return max(distances)

