def count_good_positions(n, m, plan):
    count = 0
    for i in range(n):
        for j in range(m):
            if plan[i][j] == 1:
                continue
            directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
            for dx, dy in directions:
                x, y = i + dx, j + dy
                while 0 <= x < n and 0 <= y < m:
                    if plan[x][y] == 1:
                        count += 1
                        break
                    x, y = x + dx, y + dy
    return count

