def min_changes_to_permutation(sequence):
    n = len(sequence)
    # Check if the sequence is already a permutation
    if sorted(sequence) == list(range(1, n + 1)):
        return 0

    # Create a frequency dictionary to count occurrences of each element
    frequency = {}
    for num in sequence:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    # Count the number of elements that need to be replaced
    replacements = 0
    for num in range(1, n + 1):
        if num not in frequency or frequency[num] == 0:
            replacements += 1

    return replacements

