def can_form_palindromes(s, k):
    if len(s) % k != 0:
        return False

    # Get the length of the strings
    n = len(s) // k

    # Check each chunk of the string
    for i in range(k):
        chunk = s[i*n:(i+1)*n]
        if not is_palindrome(chunk):
            return False

    return True

