def recover_room_assignment(n, events):
    left_entrance = [False] * 10
    right_entrance = [False] * 10
    current_assignments = [0] * 10

    for event in events:
        if event == 'L':
            for i in range(10):
                if not left_entrance[i] and current_assignments[i] == 0:
                    current_assignments[i] = 1
                    left_entrance[i] = True
                    break
        elif event == 'R':
            for i in range(9, -1, -1):
                if not right_entrance[i] and current_assignments[i] == 0:
                    current_assignments[i] = 1
                    right_entrance[i] = True
                    break
        else:
            room = int(event)
            current_assignments[room] = 0
            left_entrance[room] = False
            right_entrance[room] = False

    return ''.join(['1' if assignment == 1 else '0' for assignment in current_assignments])

