def largest_subrectangle_sum(a, b, x):
    n, m = len(a), len(b)
    c = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            c[i][j] = a[i - 1] * b[j - 1] + c[i - 1][j] + c[i][j - 1] - c[i - 1][j - 1]

    result = 0
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            for k in range(i, n + 1):
                for l in range(j, m + 1):
                    if c[k][l] - c[k][j - 1] - c[i - 1][l] + c[i - 1][j - 1] <= x:
                        area = (k - i + 1) * (l - j + 1)
                        if area > result:
                            result = area

    return result if result > 0 else 0

