from typing import List

def find_unhandled_crimes(crimes: List[int]) -> int:
    officers = []
    unhandled_crimes = 0

    for crime in crimes:
        if crime == -1:
            if officers:
                officers.pop()
            else:
                unhandled_crimes += 1
        else:
            officers.extend([crime] * crime)

    return unhandled_crimes

