def calculate_expression(expression):
    stack = []
    for char in expression:
        if char.isdigit():
            stack.append(int(char))
        elif char in "+-*/":
            b = stack.pop()
            a = stack.pop()
            if char == "+":
                stack.append(a + b)
            elif char == "-":
                stack.append(a - b)
            elif char == "*":
                stack.append(a * b)
            elif char == "/":
                stack.append(a // b)
    return stack[0]

