def compute_subset_sum(n, computers, mod=10**9 + 7):
    subset_sums = [0] * (1 << n)
    subset_sums[0] = 0
    for i in range(1, 1 << n):
        subset = []
        for j in range(n):
            if i & (1 << j):
                subset.append(computers[j])
        subset_sums[i] = max(subset) - min(subset)
    return sum(subset_sums) % mod

