    while True:
        # Check if any swapping operation can be applied
        for i in range(len(s) - 1):
            if s[i] == 'y' and s[i + 1] == 'x':
                s = s[:i] + s[i + 1] + s[i] + s[i + 2:]
                break
        else:
            # No swapping operation can be applied, check if any removal operation can be applied
            for i in range(len(s) - 1):
                if s[i] == 'x' and s[i + 1] == 'y':
                    s = s[:i] + s[i + 2:]
                    break
            else:
                # No removal operation can be applied, break the loop
                break
        if len(s) == 0:
