from itertools import combinations

def select_best_pair(n, allowed_sum, prices):
    # Generate all possible pairs of items
    pairs = list(combinations(prices, 2))

    # Find the pair with the highest price sum not exceeding the allowed amount
    best_pair = None
    max_sum = 0
    for pair in pairs:
        if sum(pair) <= allowed_sum:
            if sum(pair) > max_sum:
                max_sum = sum(pair)
                best_pair = pair

    # Return the sum of the best pair or 'NONE' if no pair is valid
    if best_pair is None:
        return 'NONE'
    else:
        return sum(best_pair)

