import sys
from collections import defaultdict

def count_connected_components(n, m, nums):
    graph = defaultdict(list)

    # Build the graph
    for i in range(m):
        for j in range(i+1, m):
            if (nums[i] & nums[j]) == 0:
                graph[nums[i]].append(nums[j])
                graph[nums[j]].append(nums[i])

    # DFS to count connected components
    visited = set()
    def dfs(node):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                dfs(neighbor)

    count = 0
    for num in nums:
        if num not in visited:
            dfs(num)
            count += 1

    return count

