def bubble_sort(arr):
    n = len(arr)
    exchanges = 0
    for i in range(n):
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
                exchanges += 1
    return exchanges

