class Node:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None
        self.parent = None

def insert(root, key):
    if root is None:
        return Node(key)
    if key < root.key:
        root.left = insert(root.left, key)
        root.left.parent = root
    else:
        root.right = insert(root.right, key)
        root.right.parent = root
    return root

def find(root, key):
    while root is not None:
        if key < root.key:
            root = root.left
        elif key > root.key:
            root = root.right
        else:
            return True
    return False

def delete(root, key):
    if root is None:
        return None
    if key < root.key:
        root.left = delete(root.left, key)
    elif key > root.key:
        root.right = delete(root.right, key)
    else:
        if root.left is None:
            return root.right
        elif root.right is None:
            return root.left
        else:
            y = min(root.right, key=root.right.key)
            root.key = y.key
            root.right = delete(root.right, y.key)
    return root

def inorder(root):
    if root is None:
        return []
    return inorder(root.left) + [root.key] + inorder(root.right)

def preorder(root):
    if root is None:
        return []
    return [root.key] + preorder(root.left) + preorder(root.right)

def print_tree(root):
    inorder_keys = inorder(root)
    preorder_keys = preorder(root)
    print(" ".join(map(str, inorder_keys)))
    print(" ".join(map(str, preorder_keys)))

