def is_strong_palindrome(s):
    if len(s) % 2 == 0:
        return False

    left, right = 0, len(s) - 1

    while left < right:
        if s[left] != s[right]:
            return False

        left += 1
        right -= 1

    left, right = 0, (len(s) - 3) // 2

    while left < right:
        if s[left] != s[right]:
            return False

        left += 1
        right -= 1

    return True

