def decompress_string(compressed_string):
    restored_string = ""
    i = 0
    while i < len(compressed_string):
        if compressed_string[i] == "@":
            count = int(compressed_string[i+1])
            char = compressed_string[i+2]
            restored_string += char * count
            i += 3
        else:
            restored_string += compressed_string[i]
            i += 1
    return restored_string

