import sys

def find_optimal_score(player1_deck, player2_deck):
    n = len(player1_deck)
    m = len(player2_deck)

    # Initialize scores
    player1_score = 0
    player2_score = 0

    # Iterate through the decks
    for i in range(n):
        if player1_deck[i] != -1:
            player1_score += player1_deck[i]
        else:
            # Find the top scoring card from player2's deck
            top_jamming_card = -1
            for j in range(m):
                if player2_deck[j] != -1 and (top_jamming_card == -1 or player2_deck[j] > top_jamming_card):
                    top_jamming_card = player2_deck[j]
            if top_jamming_card != -1:
                player1_score += top_jamming_card
            else:
                break

    for i in range(m):
        if player2_deck[i] != -1:
            player2_score += player2_deck[i]
        else:
            # Find the top scoring card from player1's deck
            top_jamming_card = -1
            for j in range(n):
                if player1_deck[j] != -1 and (top_jamming_card == -1 or player1_deck[j] > top_jamming_card):
                    top_jamming_card = player1_deck[j]
            if top_jamming_card != -1:
                player2_score += top_jamming_card
            else:
                break

    return player1_score - player2_score

