def play_game(matrix):
    current_player = 'Ashish'
    while True:
        valid_moves = []
        for i in range(n):
            for j in range(m):
                if matrix[i][j] == 0 and is_valid_move(matrix, i, j):
                    valid_moves.append((i, j))
        if not valid_moves:
            break
        row, col = valid_moves[0]
        matrix[row][col] = 1
        if current_player == 'Ashish':
            current_player = 'Vivek'
        else:
            current_player = 'Ashish'
    if current_player == 'Ashish':
        return 'Vivek'
    else:
        return 'Ashish'

