import sys

def min_balance_weight(n_r, n_g, n_b, r, g, b):
    r.sort()
    g.sort()
    b.sort()

    min_diff = float('inf')
    for i in range(n_r):
        for j in range(n_g):
            for k in range(n_b):
                min_diff = min(min_diff, (r[i] - g[j]) ** 2 + (g[j] - b[k]) ** 2 + (b[k] - r[i]) ** 2)

    return min_diff

