def count_ways(n, k):
    if n < 2 or k < 1:
        return 0

    primes = [2]
    for i in range(3, n + 1, 2):
        is_prime = True
        for prime in primes:
            if i % prime == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(i)

    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for prime in primes:
        for j in range(k, 0, -1):
            for i in range(prime, n + 1):
                dp[i][j] += dp[i - prime][j - 1]

    return dp[n][k]

