import re

def evaluate_expression(expression):
    def apply_operator(operators, operands):
        while operators and operators[-1] != '(':
            op = operators.pop()
            b = operands.pop()
            a = operands.pop()
            operands.append(apply_op(op, a, b))
        return operands[0]

    def apply_op(op, a, b):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            return a // b

    operators = []
    operands = []

    for char in expression:
        if char.isdigit():
            operands.append(int(char))
        elif char in "+-*/":
            while operators and operators[-1] != '(' and precedence(char) <= precedence(operators[-1]):
                apply_operator(operators, operands)
            operators.append(char)
        elif char == '(':
            operators.append(char)
        elif char == ')':
            while operators[-1] != '(':
                apply_operator(operators, operands)
            operators.pop()

    while operators:
        apply_operator(operators, operands)

    return operands[0]

def precedence(op):
    if op in "+-":
        return 1
    elif op in "*/":
        return 2
    else:
        return 0

