import math

def count_valid_numbers(n):
    count = 0
    for m in range(2, n + 1):
        product = 1
        for i in range(2, int(math.sqrt(m)) + 1):
            if m % i == 0:
                product *= i
                if i != m // i:
                    product *= m // i
        if product > 2 * m:
            count += 1
    return count

