def flip_to_max_ones(n, nums):
    max_ones = 0
    for i in range(n):
        for j in range(i, n):
            temp = nums.copy()
            for k in range(i, j + 1):
                temp[k] = 1 - temp[k]
            max_ones = max(max_ones, sum(temp))
    return max_ones

