def longest_good_sequence():
    n = int(sys.stdin.readline().strip())
    a = list(map(int, sys.stdin.readline().strip().split()))

    # Initialize the dynamic programming array
    dp = [1] * n

    # Iterate through the array to find the longest good sequence
    for i in range(1, n):
        for j in range(i):
            if a[i] > a[j] and gcd(a[i], a[j]) > 1:
                dp[i] = max(dp[i], dp[j] + 1)

    # The length of the longest good sequence is the maximum value in the dp array
    return max(dp)

