class BST:
    def __init__(self):
        self.root = None

    def insert(self, key):
        new_node = Node(key)
        if self.root is None:
            self.root = new_node
        else:
            self._insert(self.root, new_node)

    def _insert(self, node, new_node):
        if new_node.key < node.key:
            if node.left is None:
                node.left = new_node
                new_node.parent = node
            else:
                self._insert(node.left, new_node)
        else:
            if node.right is None:
                node.right = new_node
                new_node.parent = node
            else:
                self._insert(node.right, new_node)

    def find(self, key):
        return self._find(self.root, key)

    def _find(self, node, key):
        if node is None or node.key == key:
            return node
        elif key < node.key:
            return self._find(node.left, key)
        else:
            return self._find(node.right, key)

    def delete(self, key):
        node = self.find(key)
        if node is None:
            return
        if node.left is None and node.right is None:
            if node.parent is None:
                self.root = None
            elif node.parent.left == node:
                node.parent.left = None
            else:
                node.parent.right = None
        elif node.left is None or node.right is None:
            if node.left is not None:
                child = node.left
            else:
                child = node.right
            child.parent = node.parent
            if node.parent is None:
                self.root = child
            elif node.parent.left == node:
                node.parent.left = child
            else:
                node.parent.right = child
        else:
            successor = self._find_min(node.right)
            node.key = successor.key
            self.delete(successor.key)

    def _find_min(self, node):
        while node.left is not None:
            node = node.left
        return node

    def print_inorder(self):
        self._print_inorder(self.root)

    def _print_inorder(self, node):
        if node is not None:
            self._print_inorder(node.left)
            print(node.key, end=' ')
            self._print_inorder(node.right)

    def print_preorder(self):
        self._print_preorder(self.root)

    def _print_preorder(self, node):
        if node is not None:
            print(node.key, end=' ')
            self._print_preorder(node.left)
            self._print_preorder(node.right)

