        self.root = None

    def insert(self, key):
        new_node = Node(key)
        if self.root is None:
            self.root = new_node
            return
        current = self.root
        while True:
            if key < current.key:
                if current.left is None:
                    current.left = new_node
                    new_node.parent = current
                    break
                current = current.left
            else:
                if current.right is None:
                    current.right = new_node
                    new_node.parent = current
                    break
                current = current.right

    def find(self, key):
        current = self.root
        while current is not None:
            if key == current.key:
                return True
            elif key < current.key:
                current = current.left
            else:
                current = current.right
        return False

    def delete(self, key):
        node = self.find_node(key)
        if node is None:
            return
        if node.left is None and node.right is None:
            if node.parent.left == node:
                node.parent.left = None
            else:
                node.parent.right = None
        elif node.left is None or node.right is None:
            if node.left is not None:
                child = node.left
            else:
                child = node.right
            if node.parent.left == node:
                node.parent.left = child
            else:
                node.parent.right = child
            child.parent = node.parent
        else:
            successor = self.find_successor(node)
            node.key = successor.key
            self.delete(successor.key)

    def find_node(self, key):
        current = self.root
        while current is not None:
            if key == current.key:
                return current
            elif key < current.key:
                current = current.left
            else:
                current = current.right
        return None

    def find_successor(self, node):
        current = node.right
        while current.left is not None:
            current = current.left
        return current

    def inorder_traversal(self):
        result = []
        self.inorder_traversal_helper(self.root, result)
        return result

    def inorder_traversal_helper(self, node, result):
        if node is None:
            return
        self.inorder_traversal_helper(node.left, result)
        result.append(node.key)
        self.inorder_traversal_helper(node.right, result)

    def preorder_traversal(self):
        result = []
        self.preorder_traversal_helper(self.root, result)
        return result

    def preorder_traversal_helper(self, node, result):
        if node is None:
            return
        result.append(node.key)
        self.preorder_traversal_helper(node.left, result)
        self.preorder_traversal_helper(node.right, result)

