        self.left = None
        self.right = None
        self.parent = None

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        node = Node(key)
        if self.root is None:
            self.root = node
        else:
            self._insert_recursive(self.root, node)

    def _insert_recursive(self, current, node):
        if current.key < node.key:
            if current.right is None:
                current.right = node
                node.parent = current
            else:
                self._insert_recursive(current.right, node)
        else:
            if current.left is None:
                current.left = node
                node.parent = current
            else:
                self._insert_recursive(current.left, node)

    def find(self, key):
        return self._find_recursive(self.root, key) is not None

    def _find_recursive(self, current, key):
        if current is None or current.key == key:
            return current
        if current.key < key:
            return self._find_recursive(current.right, key)
        else:
            return self._find_recursive(current.left, key)

    def delete(self, key):
        node = self._find_recursive(self.root, key)
        if node is None:
            return

        if node.left is None and node.right is None:
            if node.parent is None:
                self.root = None
            else:
                if node.parent.left == node:
                    node.parent.left = None
                else:
                    node.parent.right = None
        elif node.left is None:
            if node.parent is None:
                self.root = node.right
                self.root.parent = None
            else:
                if node.parent.left == node:
                    node.parent.left = node.right
                else:
                    node.parent.right = node.right
                node.right.parent = node.parent
        elif node.right is None:
            if node.parent is None:
                self.root = node.left
                self.root.parent = None
            else:
                if node.parent.left == node:
                    node.parent.left = node.left
                else:
                    node.parent.right = node.left
                node.left.parent = node.parent
        else:
            successor = self._find_min_node(node.right)
            node.key = successor.key
            self.delete(successor.key)

    def _find_min_node(self, node):
        current = node
        while current.left is not None:
            current = current.left
        return current

    def print_inorder(self):
