    for color in colors:
        color_counts[color - 1] += 1

    # Check if the desired counts are possible
    for i in range(n):
        current_counts = [0] * m
        for j in range(i, n):
            for k in range(m):
                current_counts[k] += colors[j] == k + 1
            if current_counts == desired_counts:
                return "YES"
    return "NO"

