import re

def most_frequent_word(text):
    words = re.findall(r'\b\w+\b', text)
    word_counts = {}
    for word in words:
        if word in word_counts:
            word_counts[word] += 1
        else:
            word_counts[word] = 1
    return max(word_counts, key=word_counts.get)

def longest_word(text):
    words = re.findall(r'\b\w+\b', text)
    return max(words, key=len)

