from itertools import combinations

def manhattan_distance(p1, p2):
    return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

def is_self_intersecting(polygon):
    n = len(polygon)
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if (polygon[i][0] - polygon[j][0]) * (polygon[j][1] - polygon[k][1]) + \
                   (polygon[j][0] - polygon[k][0]) * (polygon[k][1] - polygon[i][1]) + \
                   (polygon[k][0] - polygon[i][0]) * (polygon[i][1] - polygon[j][1]) == 0:
                    return True
    return False

def max_perimeter(n, points):
    max_perimeter = 0
    for k in range(3, n + 1):
        for polygon in combinations(points, k):
            if not is_self_intersecting(polygon):
                perimeter = sum(manhattan_distance(polygon[i], polygon[(i + 1) % k]) for i in range(k))
                max_perimeter = max(max_perimeter, perimeter)
    return max_perimeter

