import heapq
from collections import defaultdict

def min_cost_to_connect_all_towns(N, coordinates):
    def distance(a, b):
        return min(abs(a[0] - b[0]), abs(a[1] - b[1]))

    # Build a graph with edges between towns
    graph = defaultdict(list)
    for i in range(N):
        for j in range(i + 1, N):
            x1, y1 = coordinates[i]
            x2, y2 = coordinates[j]
            cost = distance((x1, y1), (x2, y2))
            graph[i].append((j, cost))
            graph[j].append((i, cost))

    # Use Kruskal's algorithm to find the minimum spanning tree
    parent = list(range(N))
    rank = [0] * N

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x == root_y:
            return
        if rank[root_x] < rank[root_y]:
            parent[root_x] = root_y
        elif rank[root_x] > rank[root_y]:
            parent[root_y] = root_x
        else:
            parent[root_y] = root_x
            rank[root_x] += 1

    mst_cost = 0
    edges = []
    for u, neighbors in graph.items():
        for v, cost in neighbors:
            edges.append((cost, u, v))

    heapq.heapify(edges)

    while edges:
        cost, u, v = heapq.heappop(edges)
        if find(u) != find(v):
            union(u, v)
            mst_cost += cost

    return mst_cost

