import sys

def partition_integers(N, K):
    if N == 1:
        if K <= 3:
            return f"{K} {K+1} {K+2}"
        else:
            return "-1"
    else:
        if K + 3 * N - 1 > 3 * (N - 1) + 1:
            return "-1"
        else:
            result = []
            for i in range(N):
                start = K + i * 3
                end = start + 3
                if end > K + 3 * N - 1:
                    end = K + 3 * N - 1
                result.append(f"{start} {start+1} {end}")
            return "\n".join(result)

