def matrix_chain_multiplication(dims):
    n = len(dims)
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = float('inf')
            for k in range(i, j):
                cost = dp[i][k] + dp[k + 1][j] + dims[i][0] * dims[k][1] * dims[j][1]
                if cost < dp[i][j]:
                    dp[i][j] = cost

    return dp[0][n - 1]

