import math

def get_prime_factors(n):
    factors = []
    i = 2
    while i <= math.sqrt(n):
        if n % i == 0:
            factors.append(i)
            while n % i == 0:
                n //= i
        i += 1
    if n > 1:
        factors.append(n)
    return factors

def key_number(n):
    factors = get_prime_factors(n)
    prime_factors = [factor for factor in factors if factor > 1]
    if not prime_factors:
        return 0
    max_prime = max(prime_factors)
    sum_of_other_prime_factors = sum(prime_factors) - max_prime
    return max_prime - sum_of_other_prime_factors

