def can_form_interval(n, m, lightsabers, desired_counts):
    # Count the occurrences of each color in the lightsabers list
    color_counts = [0] * m
    for color in lightsabers:
        color_counts[color - 1] += 1

    # Check if the desired counts can be achieved by forming an interval
    for i in range(n):
        current_counts = [0] * m
        for j in range(i, n):
            for k in range(m):
                current_counts[k] += lightsabers[j] == k + 1
            if current_counts == desired_counts:
                return "YES"
    return "NO"

