def max_happiness(N, activities):
    # Create a 3D DP table to store the maximum happiness for each day and activity combination
    dp = [[[0] * (N + 1) for _ in range(3)] for _ in range(N + 1)]

    # Fill the DP table
    for day in range(1, N + 1):
        for activity in range(3):
            for prev_activity in range(3):
                if prev_activity != activity:
                    dp[day][activity][day] = max(dp[day][activity][day], dp[day - 1][prev_activity][day - 1] + activities[day - 1][activity - 1])

    # Return the maximum happiness for the last day and any activity
    return max(dp[N][activity][N] for activity in range(3))

