def max_happiness(N, activities):
    dp = [[0] * 3 for _ in range(N + 1)]

    for i in range(1, N + 1):
        for j in range(3):
            dp[i][j] = dp[i - 1][j]
            for k in range(3):
                if k != j:
                    dp[i][j] = max(dp[i][j], dp[i - 1][k] + activities[i - 1][j])

    return max(dp[N])

