def is_good_substring(s):
    vowels = set('aeiouAEIOU')
    vowel_count = 0
    consonant_count = 0

    for char in s:
        if char in vowels:
            vowel_count += 1
        else:
            consonant_count += 1

    return vowel_count <= 2 * consonant_count

def longest_good_substring(s):
    max_length = 0
    max_count = 0

    for i in range(len(s)):
        for j in range(i, len(s)):
            if is_good_substring(s[i:j+1]):
                length = j - i + 1
                if length > max_length:
                    max_length = length
                    max_count = 1
                elif length == max_length:
                    max_count += 1

    if max_length == 0:
        return "No solution"
    else:
        return f"{max_length} {max_count}"

