                length = j - i + 1
                if length > max_length:
                    max_length = length
                    max_count = 1
                elif length == max_length:
                    max_count += 1

    if max_length == 0:
        return "No solution"
    else:
        return f"{max_length} {max_count}"

def is_good_substring(substring):
    vowels = set("aeiouAEIOU")
    vowel_count = sum(1 for char in substring if char in vowels)
    consonant_count = sum(1 for char in substring if char not in vowels)
    return vowel_count <= 2 * consonant_count

