    elif n < 100:
        return tens[n//10] + ( '-' + ones[n%10] if n%10 != 0 else '')
    elif n < 1000:
        return ones[n//100] + ' hundred' + ( ('' if n%100 == 0 else ' and ') + number_to_words(n%100) if n%100 != 0 else '')
    else:
        return 'number out of range'

