def is_acyclic(graph):
    visited = [False] * len(graph)
    stack = []
    for i in range(len(graph)):
        if not visited[i]:
            if not dfs(graph, i, visited, stack):
                return False
    return True

def dfs(graph, node, visited, stack):
    visited[node] = True
    stack.append(node)
    for neighbor in graph[node]:
        if not visited[neighbor]:
            if not dfs(graph, neighbor, visited, stack):
                return False
        elif neighbor in stack:
            return False
    stack.pop()
    return True

def can_make_acyclic(n, m, edges):
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u-1].append(v-1)

    if is_acyclic(graph):
        return "YES"

    for i in range(m):
        u, v = edges[i]
        graph[u-1].remove(v-1)
        if is_acyclic(graph):
            return "YES"
        graph[u-1].append(v-1)

    return "NO"

