import sys

def solve(S):
    MOD = 10**9 + 7
    dp = [0] * (S + 1)
    dp[0] = 1  # There's one way to get a sum of 0: use no terms
    for i in range(1, S + 1):
        for j in range(3, i + 1):
            dp[i] = (dp[i] + dp[i - j]) % MOD
    return dp[S]

