def is_strong_palindrome(s):
    n = len(s)
    # Check if the string is a palindrome
    if s != s[::-1]:
        return False

    # Check if the substring formed by the first (n-1)/2 characters is a palindrome
    if s[:n//2] != s[:n//2][::-1]:
        return False

    # Check if the substring formed by the (n+3)/2-th through n-th characters is a palindrome
    if s[n//2+1:] != s[n//2+1:][::-1]:
        return False

    return True

