def is_valid_backbag(s, k):
    n = len(s)
    if n % k != 0:
        return "NO"

    length = n // k
    palindrome_set = set()

    for i in range(k):
        palindrome = s[i * length:(i + 1) * length]
        if palindrome != palindrome[::-1]:
            return "NO"
        palindrome_set.add(palindrome)

    for i in range(1, k):
        if s[i * length:(i + 1) * length] not in palindrome_set:
            return "NO"

    return "YES"

