    def dfs(node):
        if visited[node]:
            if recursion_stack[node]:
                return True
            return False
        visited[node] = True
        recursion_stack[node] = True
        for neighbor in graph[node]:
            if dfs(neighbor):
                return True
        recursion_stack[node] = False
        return False

    # Check for cycle in each component of the graph
    for i in range(V):
        if not visited[i]:
            if dfs(i):
                return 1
    return 0

