def find_cycle(n, edges):
    visited = [False] * n
    on_stack = [False] * n
    parent = [-1] * n

    def dfs(node):
        visited[node] = True
        on_stack[node] = True

        for neighbor in edges[node]:
            if not visited[neighbor]:
                parent[neighbor] = node
                if dfs(neighbor):
                    return True
            elif on_stack[neighbor]:
                return True

        on_stack[node] = False
        return False

    for i in range(n):
        if not visited[i]:
            if dfs(i):
                return 1

    return 0

