def is_hamming(n):
    if n == 1:
        return True
    if n % 2 == 0:
        return is_hamming(n // 2)
    if n % 3 == 0:
        return is_hamming(n // 3)
    if n % 5 == 0:
        return is_hamming(n // 5)
    return False

def count_hamming(m, n):
    count = 0
    for i in range(m, n + 1):
        if is_hamming(i):
            count += 1
    return count

