def longest_non_boring_substring(s, n, b):
    max_len = 0
    max_pos = 0
    for i in range(len(s)):
        for j in range(i, len(s)):
            if not any(substring in s[i:j+1] for substring in b):
                if j - i + 1 > max_len:
                    max_len = j - i + 1
                    max_pos = i
    return max_len, max_pos

